/**
 * Parse CSV text into rows of string fields.
 *
 * - Fields are separated by commas.
 * - A field wrapped in double quotes may contain commas and line breaks;
 *   a doubled quote ("") inside a quoted field represents one double quote.
 * - Lines end with "\n" or "\r\n".
 * - A final line break does not add an empty row; empty text returns [].
 *
 * @param {string} text
 * @returns {string[][]}
 */
export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseCsv expects a string');
  }
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let fieldStarted = false;
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
    fieldStarted = false;
  };

  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"' && !fieldStarted) {
      inQuotes = true;
      fieldStarted = true;
      i += 1;
      continue;
    }

    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }

    if (ch === '\r' && text[i + 1] === '\n') {
      endRow();
      i += 2;
      continue;
    }

    if (ch === '\n' || ch === '\r') {
      endRow();
      i += 1;
      continue;
    }

    field += ch;
    fieldStarted = true;
    i += 1;
  }

  // A final line break already ended its row; only add a pending row otherwise.
  if (field !== '' || fieldStarted || row.length > 0 || inQuotes) {
    endRow();
  }

  return rows;
}

/**
 * Map parsed CSV rows to objects using the first row as the header.
 * Short rows are padded with empty strings for missing columns.
 *
 * @param {string[][]} rows
 * @returns {Record<string, string>[]}
 */
export function toObjects(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return [];
  const header = rows[0];
  return rows.slice(1).map((row) => {
    const obj = {};
    for (let i = 0; i < header.length; i += 1) {
      obj[header[i]] = row[i] === undefined ? '' : row[i];
    }
    return obj;
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from '../src/csv.js';

test('parseCsv splits comma-separated fields (c1)', () => {
  assert.deepEqual(parseCsv('a,b,c'), [['a', 'b', 'c']]);
  assert.deepEqual(parseCsv('a,b,c\nd,e,f'), [
    ['a', 'b', 'c'],
    ['d', 'e', 'f'],
  ]);
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
});

test('parseCsv supports quoted fields with commas and line breaks (c2)', () => {
  assert.deepEqual(parseCsv('"a,b",c'), [['a,b', 'c']]);
  assert.deepEqual(parseCsv('"line1\nline2",x'), [['line1\nline2', 'x']]);
  assert.deepEqual(parseCsv('"he said ""hi""",y'), [['he said "hi"', 'y']]);
  assert.deepEqual(parseCsv('"a,b","c""d"'), [['a,b', 'c"d']]);
});

test('parseCsv handles LF, CRLF, trailing line breaks and empty text (c3)', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv(''), []);
  assert.deepEqual(parseCsv('a\n\nb'), [['a'], [''], ['b']]);
});

test('toObjects maps rows with the header and pads short rows (c4)', () => {
  assert.deepEqual(toObjects(parseCsv('name,age\nalice,30\nbob')), [
    { name: 'alice', age: '30' },
    { name: 'bob', age: '' },
  ]);
  assert.deepEqual(toObjects([]), []);
  assert.deepEqual(toObjects([['a', 'b']]), []);
});
